#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_BOOKS 100
#define MAX_TITLE_LEN 50

typedef struct {
    int id;
    char title[MAX_TITLE_LEN + 1];
} Book;

Book books[MAX_BOOKS];
int book_count = 0;

void display_menu() {
    printf("1. Add a book\n");
    printf("2. Search for a book by ID\n");
    printf("3. Delete a book by ID\n");
    printf("4. Display all books\n");
    printf("5. Exit\n");
}

void add_book() {
    if (book_count >= MAX_BOOKS) {
        printf("Cannot add more books. Maximum limit reached.\n");
        return;
    }

    int id;
    printf("Enter Book ID: ");
    if (scanf("%d", &id) != 1) {
        printf("Invalid input.\n");
        while (getchar() != '\n');
        return;
    }

    int duplicate = 0;
    for (int i = 0; i < book_count; i++) {
        if (books[i].id == id) {
            duplicate = 1;
            break;
        }
    }
    if (duplicate) {
        printf("Book with this ID already exists.\n");
        while (getchar() != '\n');
        return;
    }

    int c;
    while ((c = getchar()) != '\n' && c != EOF);

    printf("Enter Book Title: ");
    if (fgets(books[book_count].title, MAX_TITLE_LEN + 1, stdin) == NULL) {
        books[book_count].title[0] = '\0';
    }

    size_t len = strlen(books[book_count].title);
    if (len > 0 && books[book_count].title[len - 1] == '\n') {
        books[book_count].title[len - 1] = '\0';
        len--;
    }
    if (len > MAX_TITLE_LEN) {
        books[book_count].title[MAX_TITLE_LEN] = '\0';
    }

    books[book_count].id = id;
    book_count++;
    printf("Book added successfully.\n");
}

void search_book() {
    int id;
    printf("Enter Book ID: ");
    if (scanf("%d", &id) != 1) {
        printf("Invalid input.\n");
        while (getchar() != '\n');
        return;
    }

    int found = 0;
    for (int i = 0; i < book_count; i++) {
        if (books[i].id == id) {
            printf("Book found: ID=%d, Title=\"%s\"\n", books[i].id, books[i].title);
            found = 1;
            break;
        }
    }
    if (!found) {
        printf("Book not found.\n");
    }
}

void delete_book() {
    int id;
    printf("Enter Book ID: ");
    if (scanf("%d", &id) != 1) {
        printf("Invalid input.\n");
        while (getchar() != '\n');
        return;
    }

    int found = 0;
    int idx = -1;
    for (int i = 0; i < book_count; i++) {
        if (books[i].id == id) {
            found = 1;
            idx = i;
            break;
        }
    }
    if (found) {
        for (int i = idx; i < book_count - 1; i++) {
            books[i] = books[i + 1];
        }
        book_count--;
        printf("Book deleted successfully.\n");
    } else {
        printf("Book ID not found.\n");
    }
}

void display_all_books() {
    if (book_count == 0) {
        printf("No books in the system.\n");
        return;
    }
    for (int i = 0; i < book_count; i++) {
        printf("Book ID=%d, Title=\"%s\"\n", books[i].id, books[i].title);
    }
}

int main() {
    int choice;
    char line[256];

    while (1) {
        display_menu();
        printf("Choose an option: ");
        if (fgets(line, sizeof(line), stdin) == NULL) {
            break;
        }
        if (sscanf(line, "%d", &choice) != 1) {
            continue;
        }

        switch (choice) {
            case 1:
                add_book();
                break;
            case 2:
                search_book();
                break;
            case 3:
                delete_book();
                break;
            case 4:
                display_all_books();
                break;
            case 5:
                printf("Exiting the program...\n");
                return 0;
            default:
                printf("Invalid option. Please try again.\n");
        }
    }
    return 0;
}
